const prizes=['Giải khuyến khích','Giải ba','Giải nhì','Giải nhất','Giải đặc biệt'];
const symbols=['✧','③','②','①','♛'];
let length=4, rangeMin=0, rangeMax=9999, quotas=[3,2,1,1,1], results=prizes.map(()=>[]), busy=false;
const $=id=>document.getElementById(id);
const total=()=>quotas.reduce((a,b)=>a+b,0);
const done=()=>results.reduce((a,b)=>a+b.length,0);
const current=()=>prizes.findIndex((_,i)=>results[i].length<quotas[i]);
function makeDigits(){ $('digits').replaceChildren(...Array.from({length},()=>{const el=document.createElement('div');el.className='digit';el.textContent='0';return el})); }
function render(){const p=current();$('count').textContent=done()+' số';$('results').innerHTML=prizes.map((name,i)=>`<div class="result-group ${i===p?'active':''}"><div class="result-head"><span class="symbol">${symbols[i]}</span>${name}<small>${results[i].length}/${quotas[i]}</small></div><div class="result-numbers">${results[i].map(n=>`<span class="winner">${n}</span>`).join('')}</div></div>`).join('');$('progress-text').textContent=`${done()} / ${total()} lượt`;$('progress-fill').style.width=100*done()/total()+'%';$('steps').innerHTML=prizes.map((n,i)=>`<span class="${i===p?'current':''}">${n.replace('Giải ','')}</span>`).join('');$('format-label').textContent=`${length} chữ số · ${String(rangeMin).padStart(length,'0')}–${String(rangeMax).padStart(length,'0')}`;$('spin').disabled=busy||p<0;$('settings').disabled=busy;}
function ready(){const p=current();if(p<0){$('spin').textContent='ĐÃ HOÀN TẤT';$('next').textContent='Mở Thiết lập để bắt đầu chương trình mới.';return}$('prize').textContent=prizes[p];$('round').textContent=`Lượt ${results[p].length+1} / ${quotas[p]} của giải · ${length} chữ số`;$('next').textContent=`${total()-done()} lượt quay đang chờ`;}
function randomNumber(max){const a=new Uint32Array(1),limit=4294967296-4294967296%max;do{crypto.getRandomValues(a)}while(a[0]>=limit);return a[0]%max;}
function pick(){const used=new Set(results.flat().map(Number));const available=[];for(let n=rangeMin;n<=rangeMax;n++)if(!used.has(n))available.push(n);if(!available.length)throw new Error('Không còn số để quay');return String(available[randomNumber(available.length)]).padStart(length,'0');}
function validateRange(from,to,digitCount,drawCount){if(!/^\d+$/.test(from)||!/^\d+$/.test(to))return 'Vui lòng nhập số nguyên không âm cho khoảng quay.';const min=Number(from),max=Number(to);if(!Number.isSafeInteger(min)||!Number.isSafeInteger(max)||min>max||max>=10**digitCount)return `Khoảng quay phải từ ${'0'.repeat(digitCount)} đến ${'9'.repeat(digitCount)}, và Từ số không lớn hơn Đến số.`;if(drawCount>max-min+1)return `Khoảng này chỉ có ${max-min+1} số. Hãy giảm tổng lượt quay hoặc mở rộng khoảng quay.`;return '';}
const delay=ms=>new Promise(resolve=>setTimeout(resolve,ms));
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const pieces=Array.from({length:65},(_,i)=>{const el=document.createElement('i');el.style.left=Math.random()*100+'%';el.style.background=['#edbf65','#fff0bd','#ef7772'][i%3];el.style.animationDelay=Math.random()*.5+'s';return el});$('confetti').replaceChildren(...pieces);setTimeout(()=>$('confetti').replaceChildren(),3500)}
async function spin(){if(busy||current()<0)return;busy=true;ready();const p=current(),number=pick();$('announcement').textContent='';$('hint').textContent='May mắn đang được hé lộ…';$('spin').textContent='ĐANG QUAY…';render();const cells=[...$('digits').children];cells.forEach(c=>c.className='digit rolling');let remaining=length;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const ticker=setInterval(()=>cells.forEach((c,i)=>{if(i<remaining)c.textContent=reduced?'·':Math.floor(Math.random()*10)}),70);try{await delay(900);for(let i=length-1;i>=0;i--){remaining=i;cells[i].textContent=number[i];cells[i].className='digit locked';await delay(i===0?300:850)}results[p].push(number);$('announcement').textContent=`Chúc mừng số ${number}!`;$('hint').textContent=`Đã tìm thấy chủ nhân ${prizes[p].toLowerCase()}`;celebrate()}finally{clearInterval(ticker);busy=false;render();$('spin').textContent=current()<0?'ĐÃ HOÀN TẤT':'✦  QUAY LƯỢT TIẾP THEO';$('next').textContent=current()<0?'Đã trao tất cả giải. Mở Thiết lập để bắt đầu lại.':`Tiếp theo: ${prizes[current()]} · Lượt ${results[current()].length+1}/${quotas[current()]}`;}}
$('spin').addEventListener('click',spin);
$('settings').addEventListener('click',()=>{if(busy)return;document.querySelector(`input[name="length"][value="${length}"]`).checked=true;$('range-min').value=String(rangeMin).padStart(length,'0');$('range-max').value=String(rangeMax).padStart(length,'0');$('quotas').innerHTML=prizes.map((n,i)=>`<label class="quota-row">${n}<input aria-label="Số lượt ${n}" type="number" min="0" max="1000" step="1" required value="${quotas[i]}"></label>`).join('');$('reset-note').hidden=done()===0;$('config-error').textContent='';$('config').showModal()});
$('close').addEventListener('click',()=>$('config').close());
$('config-form').addEventListener('submit',e=>{e.preventDefault();if(busy)return;const q=[...$('quotas').querySelectorAll('input')].map(x=>Number(x.value));if(q.some(n=>!Number.isInteger(n)||n<0||n>1000)||q.reduce((a,b)=>a+b,0)===0){$('config-error').textContent='Hãy đặt ít nhất 1 lượt quay. Mỗi giải từ 0 đến 1.000 lượt.';return}const selectedLength=Number(document.querySelector('input[name="length"]:checked').value),from=$('range-min').value.trim(),to=$('range-max').value.trim();const error=validateRange(from,to,selectedLength,q.reduce((a,b)=>a+b,0));if(error){$('config-error').textContent=error;return}length=selectedLength;rangeMin=Number(from);rangeMax=Number(to);quotas=q;results=prizes.map(()=>[]);makeDigits();render();ready();$('announcement').textContent='';$('hint').textContent='Hé lộ từng chữ số từ phải sang trái ←';$('spin').textContent='✦  QUAY MAY MẮN';$('config').close()});
makeDigits();render();ready();


